package workflow

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/eriicafes/go-workflow/worlds"
)

// HookOption configures a regular hook. An empty token is generated by
// DefineHook. MinRetention keeps a completed token reserved; Force displaces
// an active owner, whose replay receives ErrHookForceClaimed.
type HookOption struct {
	Token        string
	MinRetention time.Duration
	Force        bool
}

// HookDefinition is a reusable regular-hook declaration. It does not alter
// workflow state until Create is called.
type HookDefinition[T any] struct {
	token        string
	minRetention time.Duration
	force        bool
}

// DefineHook returns a reusable regular-hook declaration.
func DefineHook[T any](options ...HookOption) HookDefinition[T] {
	option := HookOption{}
	if len(options) != 0 {
		option = options[len(options)-1]
	}
	if option.Token == "" {
		option.Token = worlds.NewHookToken()
	}
	return HookDefinition[T]{token: option.Token, minRetention: option.MinRetention, force: option.Force}
}

// Create registers this definition at the current workflow replay position.
func (d HookDefinition[T]) Create(ctx context.Context) (*Hook[T], error) {
	hook := &Hook[T]{token: d.token, minRetention: d.minRetention, force: d.force}
	return hook, hook.create(ctx)
}

// CreateHook defines and immediately registers a regular hook.
func CreateHook[T any](ctx context.Context, options ...HookOption) (*Hook[T], error) {
	return DefineHook[T](options...).Create(ctx)
}

// Hook receives one typed value after its token is resumed.
type Hook[T any] struct {
	token        string
	id           worlds.HookID
	position     *int
	webhook      *worlds.Webhook
	minRetention time.Duration
	force        bool
	received     worlds.EventID
}

func (h *Hook[T]) ID() string { return string(h.id) }

func (h *Hook[T]) Token() string { return h.token }

func (h *Hook[T]) Done(ctx context.Context) (bool, error) {
	result, _, err := h.result(ctx)
	if err != nil {
		return false, err
	}
	return result.Done, result.Err
}

func (h *Hook[T]) Await(ctx context.Context) (T, error) {
	var zero T
	result, execution, err := h.result(ctx)
	if err != nil {
		return zero, err
	}
	if result.Err != nil {
		return zero, result.Err
	}
	if result.Done {
		return result.Data, nil
	}
	execution.Suspend()
	return zero, nil
}

func (h *Hook[T]) Unwrap(ctx context.Context) T {
	value, err := h.Await(ctx)
	if err != nil {
		panic(err)
	}
	return value
}

// GetConflict reports the run that owns this hook's token.
func (h *Hook[T]) GetConflict(ctx context.Context) (worlds.RunID, bool, error) {
	result, _, err := h.result(ctx)
	if err != nil && result.ConflictRunID == "" {
		return "", false, err
	}
	if result.ConflictRunID == "" {
		return "", false, nil
	}
	return result.ConflictRunID, true, nil
}

func (h *Hook[T]) create(ctx context.Context) error {
	execution, ok := workflowExecutionFromContext(ctx)
	if !ok {
		return ErrNoWorkflow
	}
	position := execution.NextPosition()
	h.position = &position
	result, _, err := h.result(ctx)
	if err != nil {
		return err
	}
	return result.Err
}

func (h *Hook[T]) result(ctx context.Context) (worlds.DurableHookResult[T], *worlds.Execution, error) {
	execution, ok := workflowExecutionFromContext(ctx)
	if !ok {
		return worlds.DurableHookResult[T]{}, nil, ErrNoWorkflow
	}
	if h.position == nil {
		return worlds.DurableHookResult[T]{}, execution, ErrHookNotRegistered
	}
	result := worlds.DurableHook[T](ctx, worlds.DurableHookOptions{
		Execution:    execution,
		Position:     *h.position,
		Token:        h.token,
		Webhook:      h.webhook,
		MinRetention: h.minRetention,
		Force:        h.force,
	})
	h.id, h.token, h.received = result.HookID, result.Token, result.ReceivedEventID
	return result, execution, nil
}

func (h *Hook[T]) Cancel(ctx context.Context) error {
	execution, ok := workflowExecutionFromContext(ctx)
	if !ok {
		return ErrNoWorkflow
	}
	if h.id == "" {
		if _, _, err := h.result(ctx); err != nil {
			return err
		}
	}
	event := worlds.EventsCreateEvent{
		EventType:     worlds.EventTypeHookDisposed,
		CorrelationID: string(h.id),
	}
	eventCount := execution.EventCount()
	result, err := execution.World().EventsCreate(ctx, worlds.EventsCreateInput{
		RunID:   execution.Run().RunID,
		Event:   event,
		Options: worlds.EventsCreateOptions{EventCount: &eventCount},
	})
	if err != nil {
		return err
	}
	execution.Merge(result, worlds.Event{
		RunID:         execution.Run().RunID,
		EventID:       result.EventID,
		EventType:     event.EventType,
		CorrelationID: event.CorrelationID,
		Data:          event.Data,
	})
	return nil
}

func GetHook[T any](ctx context.Context, token string) (*Hook[T], bool, error) {
	client, err := clientFromContext(ctx)
	if err != nil {
		return nil, false, err
	}
	hook, err := client.HooksGetByToken(ctx, worlds.HooksGetByTokenInput{Token: token})
	if err != nil {
		if err == worlds.ErrHookNotFound {
			return nil, false, nil
		}
		return nil, false, err
	}
	return &Hook[T]{token: token, id: hook.HookID}, true, nil
}

func ResumeHook[T any](ctx context.Context, token string, value T) error {
	client, err := clientFromContext(ctx)
	if err != nil {
		return err
	}
	payload, err := json.Marshal(value)
	if err != nil {
		return fmt.Errorf("workflow: encode hook payload: %w", err)
	}
	return client.HooksResume(ctx, worlds.ClientHooksResumeInput{Token: token, Data: payload})
}

// ResumeHookWithRetries retries a hook delivery while a newly created run is
// still reaching its hook declaration.
func ResumeHookWithRetries[T any](ctx context.Context, token string, value T, attempts int) error {
	if attempts <= 0 {
		return ErrHookNotFound
	}
	for attempt := range attempts {
		err := ResumeHook(ctx, token, value)
		if !errors.Is(err, ErrHookNotFound) {
			return err
		}
		if attempt == attempts-1 {
			return err
		}
		timer := time.NewTimer(time.Duration(attempt+1) * 100 * time.Millisecond)
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-timer.C:
		}
	}
	return ErrHookNotFound
}

// NewHookToken returns a 21-character Nano ID.
func NewHookToken() string { return worlds.NewHookToken() }
